  --surface:   #ffffff;
  --ink:       #15181d;
  --muted:     #6b7280;
  --line:      #e3e6ea;
  --brand:     #c8102e;
  --brand-ink: #ffffff;
  --ok:        #1f7a45;
  --ok-bg:     #e9f6ee;
  --warn:      #9a6100;
  --warn-bg:   #fdf3e2;
  --bad:       #b3261e;
  --bad-bg:    #fdecec;
  --radius:    14px;
  --shadow:    0 1px 2px rgba(16,24,40,.06), 0 8px 24px rgba(16,24,40,.06);
  --font:      system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --mono:      ui-monospace, "Cascadia Mono", Consolas, monospace;
}

