[data-layer]::before {
  content: attr(data-layer-note);
  position: absolute; top: -11px; left: 14px;
  font-size: 11px; font-weight: 700; letter-spacing: .03em;
  padding: 2px 9px; border-radius: 999px;
  opacity: 0; pointer-events: none; transition: opacity .2s;
}
[data-layer="css"]::before { background: #2563eb; color: #fff; }
[data-layer="js"]::before  { background: #a855f7; color: #fff; }

body.show-layers [data-layer] { position: relative; }
body.show-layers [data-layer]::before { opacity: 1; }
body.show-layers [data-layer="css"] { outline: 2px dashed #2563eb; outline-offset: 3px; }
body.show-layers [data-layer="js"]  { outline: 2px dashed #a855f7; outline-offset: 3px; }
